# O(m+n)
class Solution: 
    # @param {integer[][]} matrix
    # @param {integer} target
    # @return {boolean}
    def searchMatrix(self, matrix, target):
        y = len(matrix[0]) - 1
        for x in range(len(matrix)):
            while y and matrix[x][y] &gt; target:
                y -= 1
            if matrix[x][y] == target:
                return True
        return False

