let accounts = new AccountModel(5)
accounts.getName()
console.log(&#039;Data is %s&#039;, accounts.accountsData)   

Modules in ES6
before:
module.exports = {
  port: 3000,
  getAccounts: function() {
    ...
  }
}

var service = require(&#039;module.js&#039;)
console.log(service.port) // 3000

after:
export var port = 3000
export function getAccounts(url) {
  ...
}

import {port, getAccounts} from &#039;module&#039;
console.log(port) // 3000

import * as service from &#039;module&#039;
console.log(service.port) // 3000

Proxy and Reflect
function Tree() {
      return new Proxy({}, handler);
    }
    var handler = {
      get: function (target, key, receiver) {
        if (!(key in target)) {
          target[key] = Tree();  // 自动创建一个子树
        }
        return Reflect.get(target, key, receiver);
      }
    };


 var tree = Tree();
    &gt; tree
        { }
    &gt; tree.branch1.branch2.twig = &quot;green&quot;;
    &gt; tree
        { branch1: { branch2: { twig: &quot;green&quot; } } }
    &gt; tree.branch1.branch3.twig = &quot;yellow&quot;;
        { branch1: { branch2: { twig: &quot;green&quot; },
                     branch3: { twig: &quot;yellow&quot; }}}

Generators in ES6
function *foo() {
    yield 1;
    return 2;
}

var it = foo();

console.log( it.next() ); // { value:1, done:false }
console.log( it.next() ); // { value:2, done:true }

function *foo(x) {
    var y = 2 * (yield (x + 1));
    var z = yield (y / 3);
    return (x + y + z);
}

var it = foo( 5 );

// note: not sending anything into `next()` here
console.log( it.next() );       // { value:6, done:false }
console.log( it.next( 12 ) );   // { value:8, done:false }
console.log( it.next( 13 ) );   // { value:42, done:true }

function *foo() {
    yield 1;
    yield 2;
    yield 3;
    yield 4;
    yield 5;
    return 6;
}

for (var v of foo()) {
    console.log( v );
}
// 1 2 3 4 5

console.log( v ); // still `5`, not `6`



function* outer() {
    yield &#039;begin&#039;;

    /*
     * yield* 一般用来在一个 generator 函数里“执行”另一个 generator 函数，并可以取得其返回值
     */
    var rt = yield* inner();
    console.log(rt);  // -&gt; 输出：return from inner

    yield &#039;end&#039;;
}

function* inner() {
    yield &#039;inner&#039;;
    return &#039;return from inner&#039;;
}

var it = outer(), v;

v = it.next().value;
console.log(v);            // -&gt; 输出：begin

v = it.next().value;
console.log(v);            // -&gt; 输出：inner

v = it.next().value;
console.log(v);            // -&gt; 输出：end

Generator and Promise together to avoid callback hell
function request(url) {
    return new Promise( function(resolve,reject){
        // pass an error-first style callback
        makeAjaxCall( url, function(err,text){
            if (err) reject( err );
            else resolve( text );
        } );
    } );
}

// run (async) a generator to completion
// Note: simplified approach: no error handling here
function runGenerator(g) {
    var it = g(), ret;

    // asynchronously iterate over generator
    (function iterate(val){
        ret = it.next( val );

        if (!ret.done) {
            // poor man&#039;s &quot;is it a promise?&quot; test
            if (&quot;then&quot; in ret.value) {
                // wait on the promise
                ret.value.then( iterate );
            }
            // immediate value: just send right back in
            else {
                // avoid synchronous recursion
                setTimeout( function(){
                    iterate( ret.value );
                }, 0 );
            }
        }
    })();
}

runGenerator( function *main(){
    try {
        var result1 = yield request( &quot;some.url.1&quot; );
    }
    catch (err) {
        console.log( &quot;Error: &quot; + err );
        return;
    }
    var data = JSON.parse( result1 );

    try {
        var result2 = yield request( &quot;some.url.2 + data.id );
    } catch (err) {
        console.log( &quot;Error: &quot; + err );
        return;
    }
    var resp = JSON.parse( result2 );
    console.log( &quot;The value you asked for: &quot; + resp.value );
} );

post/2016-11-20-super-tiny-vue.content:
super tiny vue implementation

简介：一个迷你vue库，虽然小但功能全面，可以作为想了解vue背后思想以及想学习vue源码而又不知如何入手的入门学习资料。代码可参考deep-in-vue
特性：

数据响应式更新
指令模板
MVVM
轻量级

功能解读
     &lt;templete&gt;
        &lt;div id=&#039;app&#039;&gt;
            &lt;div&gt;
                &lt;input v-model=&#039;counter&#039; /&gt;
                &lt;button v-on-click=&#039;add&#039;&gt;add&lt;/button&gt;
                &lt;p v-text=&#039;counter&#039;&gt;&lt;/p&gt;
            &lt;/div&gt;
        &lt;/div&gt;
     &lt;/templete&gt;

     &lt;script&gt;
    var vm = new Vue({
            id: &#039;counter&#039;,
            data: {
                counter: 1
            },
            methods: {
                add: function () {
                    this.counter += 1;
                }
            }
        })
     &lt;/script&gt;
如上为一段模板以及js脚本，我们所要实现的目标就是将 vm 实例与id为app的DOM节点关联起来，当更改vm data 的counter属性的时候，input的值和p标签的文本会响应式的改变，method中的add方法则和button的click事件绑定。
简单的说就是, 当点击button按钮的时候，触发button的点击事件回调函数add,在add方法中使counter加1，counter变化后模板中的input和p标签会自动更新。vm与模板之间是如何关联的则是通过 v-model、v-on-click、v-text这样的指令声明的。
实现思路详解

查找含指令的节点
对查找所得的节点进行指令解析、指令所对应的实现与节点绑定、 节点指令值所对应的data属性与前一步关联的指令实现绑定、data属性值通过setter通知关联的指令进行更新操作
含指令的每一个节点单独执行第二步
绑定操作完成后，初始化vm实例属性值

指令节点查找
首先来看第一步，含指令节点的查找，因为指令声明是以属性的形式，所以可以通过属性选择器来进行查找，如下所示：
&lt;input v-model=&#039;counter&#039; type=&#039;text&#039; /&gt;则可通过 querySelectorAll(‘[v-model]‘)查找即可。
//root对于根节点，els对应于模板内含指令的节点。
root = this.$el = document.getElementById(opts.el),
els  = this.$els = root.querySelectorAll(getDirSelectors(Directives))

指令解析，绑定
指令解析
同样以&lt;input v-model=&#039;counter&#039; type=&#039;text&#039; /&gt;为例，解析即得到
//name对应指令名，value对应指令值。
var directive = {
name: &#039;v-model&#039;,
value: &#039;counter&#039;
}

指令对应实现与当前节点的绑定(bindDirective)
指令实现可简单分为函数或是包含update函数的对象，如下便是v-text指令的实现代码：
text: function (el, value) {
    el.textContent = value || &#039;&#039;;
}
指令与节点的绑定即将该函数与节点绑定起来，即该函数负责该节点的更新操作，v-text的功能是更新文本值，所以如上所示
更改节点的textContent属性值。
响应式数据与节点的绑定(bindAccessors)
响应式数据这里拆分为 data 和 methods 对象，分别用来存储数据值和方法。
var vm = new Vue({
    id: &#039;counter&#039;,
    data: {
        counter: 1
    },
    methods: {
        add: function () {
            this.counter += 1;
        }
    }
})
我们上面解析得到 v-model 对于的指令值为 counter,所以这里将data中的counter与当前节点绑定。
通过2、3两步实现了类型与 textDirective-&gt;el&lt;-data.counter 的关联，当data.counter发生set(具体查看defineProperty set 用法)操作时，
data.counter得知自己被改变了，所以通知el元素需要进行更新操作，el则使用与其关联的指令(textDirective)对自身进行更新操作，从而实现了数据的
响应式。
以下三个是绑定的主体，数据发生更改，通知节点需要更新，节点通过指令更新自己。

textDirective
el
data.counter

源码部分

var prefix = &#039;v&#039;;

 /**
  * Directives
  */

var Directives = {

    /**
     * 对应于 v-text 指令
     */
    text: function (el, value) {
        el.textContent = value || &#039;&#039;;
    },
    show: function (el, value) {
        el.style.display = value ? &#039;&#039; : &#039;none&#039;;
    },

    /**
     * 对应于 v-model 指令
     */
    model: function (el, value, dirAgr, dir, vm, key) {
        let eventName = &#039;keyup&#039;;
        el.value = value || &#039;&#039;;

        /**
         * 事件绑定控制
         */
        if (el.handlers &amp;&amp; el.handlers[eventName]) {
            el.removeEventListener(eventName, el.handlers[eventName]);
        } else {
            el.handlers = {};
        }

        el.handlers[eventName] = function (e) {
            vm[key] = e.target.value;
        }

        el.addEventListener(eventName, el.handlers[eventName]);
    },
    on: {
        update: function (el, handler, eventName, directive) {
            if (!directive.handlers) {
                directive.handlers = {}
            }

            var handlers = directive.handlers;

            if (handlers[eventName]) {
                //绑定新的事件前移除原绑定的事件函数
                el.removeEventListener(eventName, handlers[eventName]);
            }
            //绑定新的事件函数
            if (handler) {
                handler = handler.bind(el);
                el.addEventListener(eventName, handler);
                handlers[eventName] = handler;
            }
        }
    }
}


/**
 * MiniVue
 */
function TinyVue (opts) {
    /**
     * root/this.$el: 根节点
     * els: 指令节点
     * bindings: 指令与data关联的桥梁
     */
    var self = this,
        root = this.$el = document.getElementById(opts.el),
        els  = this.$els = root.querySelectorAll(getDirSelectors(Directives)),
        bindings = {};
    this._bindings = bindings;

    /**
     * 指令处理
     */
    [].forEach.call(els, processNode);
    processNode(root);

    /**
     * vm响应式数据初始化
     */

    let _data = extend(opts.data, opts.methods);
    for (var key in bindings) {
        if (bindings.hasOwnProperty(key)) {
            self[key] = _data[key];
        }
    }

    function processNode (el) {
        getAttributes(el.attributes).forEach(function (attr) {
            var directive = parseDirective(attr);
            if (directive) {
                bindDirective(self, el, bindings, directive);
            }
        })
    }

    /**
     * ready
     */
    if (opts.ready &amp;&amp; typeof opts.ready == &#039;function&#039;) {
        this.ready = opts.ready;
        this.ready();
    }
}

/**************************************************************
 * @privete
 * helper methods
 */

/**
 * 获取节点属性
 * &#039;v-text&#039;=&#039;counter&#039; =&gt; {name: v-text, value: &#039;counter&#039;}
 */
function getAttributes (attributes) {
    return [].map.call(attributes, function (attr) {
        return {
            name: attr.name,
            value: attr.value
        }
    })
}

/**
 * 返回指令选择器，便于指令节点的查找
 */
function getDirSelectors (directives) {
    /**
     * 支持的事件指令
     */
    let eventArr = [&#039;click&#039;, &#039;change&#039;, &#039;blur&#039;];


    return Object.keys(directives).map(function (directive) {
        /**
         * text =&gt; &#039;v-text&#039;
         */
        return &#039;[&#039; + prefix + &#039;-&#039; + directive + &#039;]&#039;;
    }).join() + &#039;,&#039; + eventArr.map(function (eventName) {
        return &#039;[&#039; + prefix + &#039;-on-&#039; + eventName + &#039;]&#039;;
    }).join();
}

/**
 * 节点指令绑定
 */
function bindDirective (vm, el, bindings, directive) {
    //从节点属性中移除指令声明
    el.removeAttribute(directive.attr.name);

    /**
     * v-text=&#039;counter&#039;
     * v-model=&#039;counter&#039;
     * data = {
            counter: 1
        }
     * 这里的 counter 即指令的 key
     */
    var key = directive.key,
        binding = bindings[key];

    if (!binding) {
        /**
         * value 即 counter 对应的值
         * directives 即 key 所绑定的相关指令
         如：
           bindings[&#039;counter&#039;] = {
                value: 1,
                directives: [textDirective, modelDirective]
             }
         */
        bindings[key] = binding = {
            value: &#039;&#039;,
            directives: []
        }
    }
    directive.el = el;
    binding.directives.push(directive);

    //避免重复定义
    if (!vm.hasOwnProperty(key)) {
        /**
         * get/set 操作绑定
         */
        bindAccessors(vm, key, binding);
    }
}

/**
 * get/set 绑定指令更新操作
 */
function bindAccessors (vm, key, binding) {
    Object.defineProperty(vm, key, {
        get: function () {
            return binding.value;
        },
        set: function (value) {
            binding.value = value;
            binding.directives.forEach(function (directive) {
                directive.update(
                    directive.el,
                    value,
                    directive.argument,
                    directive,
                    vm,
                    key
                )
            })
        }
    })
}

function parseDirective (attr) {
    if (attr.name.indexOf(prefix) === -1) return ;

    /**
     * 指令解析
       v-on-click=&#039;onClick&#039;
       这里的指令名称为 &#039;on&#039;, &#039;click&#039;为指令的参数，onClick 为key
     */

    //移除 &#039;v-&#039; 前缀, 提取指令名称、指令参数
    var directiveStr = attr.name.slice(prefix.length + 1),
        argIndex = directiveStr.indexOf(&#039;-&#039;),
        directiveName = argIndex === -1
            ? directiveStr
            : directiveStr.slice(0, argIndex),
        directiveDef = Directives[directiveName],
        arg = argIndex === -1
            ? null
            : directiveStr.slice(argIndex + 1);

    /**
     * 指令表达式解析，即 v-text=&#039;counter&#039; counter的解析
     * 这里暂时只考虑包含key的情况
     */
    var key = attr.value;
    return directiveDef
        ? {
            attr: attr,
            key: key,
            dirname: directiveName,
            definition: directiveDef,
            argument: arg,
            /**
             * 指令本身是一个函数的情况下，更新函数即它本身，否则调用它的update方法
             */
            update: typeof directiveDef === &#039;function&#039;
                ? directiveDef
                : directiveDef.update
        }
        : null;
}

/**
 * 对象合并
 */
function extend (child, parent) {
    parent = parent || {};
    child = child || {};

    for(var key in parent) {
        if (parent.hasOwnProperty(key)) {
            child[key] = parent[key];
        }
    }

    return child;
}

post/2016-11-28-koa2.content:
Koa2 In-depth Analysis

koa核心主要是context（上下文）和middleware（中间件）组成，v2的中间件部分可以使用ES2015-2016的语法，比如async await和箭头函数，同时支持3种不同种类的中间件，普通函数，async 函数，Generator函数。先看如何使用：
普通函数的用法
app.use((ctx, next) =&gt; {
  const start = new Date();
  return next().then(() =&gt; {
    const ms = new Date() - start;
    console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
  });
});

async函数的用法
app.use(async (ctx, next) =&gt; {
  const start = new Date();
  await next();
  const ms = new Date() - start;
  console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
});

Generator函数的两种用法
app.use(co.wrap(function *(ctx, next) {
  const start = new Date();
  yield next();
  const ms = new Date() - start;
  console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
}));

const convert = require(&#039;koa-convert&#039;);
app.use(convert(function *(next) {
  const start = new Date();
  yield next;
  const ms = new Date() - start;
  console.log(`${this.method} ${this.url} - ${ms}ms`);
}));

直接用v1的语法也可以，像下面这样
app.use(function *(next) {
  const start = new Date();
  yield next;
  const ms = new Date() - start;
  console.log(`${this.method} ${this.url} - ${ms}ms`);
});

因为同时支持3种类型的中间件，所以这块改动比较大，先从注册中间件开始，也就是app.use
use(fn) {
  if (typeof fn !== &#039;function&#039;) throw new TypeError(&#039;middleware must be a function!&#039;);
  if (isGeneratorFunction(fn)) {
    fn = convert(fn);
  }
  this.middleware.push(fn);
  return this;
}

v2多了一个判断，如果是Generator函数，那就用 convert 把函数包起来，然后在push到this.middleware 这就是针对v1的写法做的兼容。或者自己把v1的中间件用 convert 包起来在use。convert源码:
function convert (mw) {
  if (typeof mw !== &#039;function&#039;) {
    throw new TypeError(&#039;middleware must be a function&#039;)
  }
  if (mw.constructor.name !== &#039;GeneratorFunction&#039;) {
    // assume it&#039;s Promise-based middleware
    return mw
  }
  const converted = function (ctx, next) {
    return co.call(ctx, mw.call(ctx, createGenerator(next)))
  }
  converted._name = mw._name || mw.name
  return converted
}

也就是利用co来wrap这个generator，返回promise,具体参考co源码
中间件运行
callback() {
  const fn = compose(this.middleware);

  if (!this.listeners(&#039;error&#039;).length) this.on(&#039;error&#039;, this.onerror);

  return (req, res) =&gt; {
    res.statusCode = 404;
    const ctx = this.createContext(req, res);
    onFinished(res, ctx.onerror);
    fn(ctx).then(() =&gt; respond(ctx)).catch(ctx.onerror);
  };
}

看第一行代码
const fn = compose(this.middleware);
现在 this.middleware 中存了一些函数，只要执行它就返回promise。这个函数有可能是 async 函数 有可能是被 convert 包装后的Generator函数，或者是被 co.wrap 包装后的Generator函数，也有可能是普通函数的中间件，反正这些函数都有一个特性，那就是执行它们，会统一返回promise。看看compose是怎么把三个种类的中间件变成可以实现中间件逻辑的函数呢？
function compose (middleware) {
  if (!Array.isArray(middleware)) throw new TypeError(&#039;Middleware stack must be an array!&#039;)
  for (const fn of middleware) {
    if (typeof fn !== &#039;function&#039;) throw new TypeError(&#039;Middleware must be composed of functions!&#039;)
  }

  /**
   * @param {Object} context
   * @return {Promise}
   * @api public
   */

  return function (context, next) {
    // last called middleware #
    let index = -1
    return dispatch(0)
    function dispatch (i) {
      if (i &lt;= index) return Promise.reject(new Error(&#039;next() called multiple times&#039;))
      index = i
      const fn = middleware[i] || next
      if (!fn) return Promise.resolve()
      try {
        return Promise.resolve(fn(context, function next () {
          return dispatch(i + 1)
        }))
      } catch (err) {
        return Promise.reject(err)
      }
    }
  }
}



首先看返回值，返回的是一个中间件函数｀function (context, next)｀，我们从前面｀koa callback｀函数的这行代码中可以观察到，（fn就是compose返回的中间件函数）一次fn的调用就结束了整个请求，所以fn最终的作用就是依次调用所有的中间件
fn(ctx).then(() =&gt; respond(ctx)).catch(ctx.onerror);



然后是dispatch函数，这个函数的返回值是一个Promise对象(Promise.resolve和Promise.reject是将一个现有对象转化为一个promise对象)，这个Promise对象是由原始的中间件函数构造而成的。


将上下文context和next函数传递给原始中间件对象，这里的next函数是递归的关键，next函数返回dispatch函数执行结果，也就是下一个被包装成Promise对象的中间件函数，这也就是为什么我们在koa2中执行完一个中间件，如果还需要执行下一个中间件的时候，需要执行await next()的原因


看具体过程
首先在执行到匿名函数的时候（就是return返回的那个函数），会执行 dispatch，并传一个参数 0，其次就是在 dispatch 执行的过程中会自己调用自己，递归调用。i 其实是用来在 this.middleware 中获取中间件的下标．这行代码获取中间件const fn = middleware[i] || next,取到中间件之后
return Promise.resolve(fn(context, function next () {
  return dispatch(i + 1)
}))

执行中间件并传递两个参数，context 和 next函数，context是koa中的上下文，next就是return一个dispatch 的执行结果，注意那个参数 i+1，传递一个 i+1，就相当于一旦执行next函数，就等同于执行下一个中间件。

一个中间件只能执行一次next，否则逻辑上会出现问题，为了避免这个问题，在 dispatch 中一开始就做了判断，就是一开始index和i的比较。

在中间件中，我们通常会这样使用await next();async的语法是，await后面会跟一个promise，await会等待promise，等promise执行完了，在往下执行．而我们的这些中间件，都有一个特点，执行完会返回promise，所以正好被await监听。
我们中间件本身返回的就是promise，为什么会被Promise.resolve包起来？这里是一个兼容写法，如果只支持async函数当然没问题，但我们的中间件除了支持async函数外，还支持普通函数．如果中间件使用async函数写的，流程大概是这样的：


先执行第一个中间件（因为默认会先执行一次dispatch(0)），这个中间件会返回promise，koa会监听这个promise，一旦成功或者失败，都会做出不同的处理，并结束这次响应


在执行中间件逻辑的时候，我们会执行这样一段代码 await next();，在这里手动触发第二个中间件执行，第二个中间件和第一个中间件一样，也会返回promise．await会监听这个promise，什么时候执行完了，什么时候继续执行第一个中间件后续的代码。（中间件的回逆就是这样实现的）


在第二个中间件触发的时候，也会执行 await next(); 这样一段代码来触发第三个中间件并等待第三个中间件执行完了在执行后续代码，否则就一直等，以此类推
所以就造成了这样一个现象，第一个中间件代码执行一半停在这了，触发了第二个中间件的执行，第二个中间件执行了一半停在这了，触发了第三个中间件的执行，然后，，，，，，第一个中间件等第二个中间件，第二个中间件等第三个中间件，，，，，，第三个中间件全部执行完毕，第二个中间件继续执行后续代码，第二个中间件代码全部执行完毕，执行第一个中间件后续代码，然后结束．



async函数配合中间件使用的条件

执行后返回promise
函数内部可以通过await暂停函数，并等待下一个中间件执行完成后，继续执行

中间件的实现逻辑 - 普通函数
首先我们看下普通函数的用法
app.use((ctx, next) =&gt; {
  const start = new Date();
  return next().then(() =&gt; {
    const ms = new Date() - start;
    console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
  });
});

先说第一个条件，「执行后返回promise」上面我们说过，我们的中间件在 dispatch 中会被 Promise.resolve 包住并返回，所以第一个条件满足．再说第二个条件，「中间件内部可以监听promise并等待promise接收后执行后续代码」很明显，第二个条件也满足，因为普通函数的写法是异步的，后续代码在then里面。（async也不过是看起来同步而已，其实是同样的逻辑）
中间件的实现逻辑 - Generator函数
先看看用法
app.use(co.wrap(function *(ctx, next) {
  const start = new Date();
  yield next();
  const ms = new Date() - start;
  console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
}));

首先第一个条件「执行后返回promise」可以看到中间件是用 co.wrap 包起来的，co.wrap会返回promise，参考co的源码，第一个条件满足．再说第二个条件，「中间件内部可以监听promise并等待promise接收后执行后续代码」co 与async一样，yield后面可以跟一个promise，co会监听这个promise，什么时候这个promise执行完了。什么时候执行后续的代码，这点跟async是一模一样的，只是写法略有不同，第二个条件也满足．

post/2016-12-02-webpack.content:
webpack使用

Webpack your bags
原文： Webpack your bags(by Maxime Fabre)
Webpack your bags

之前你可能已经听说过这个很酷的叫webpack工具，如果你没仔细了解过这个工具，你可能会有些困惑，因为有人说他它是像Gulp之类构建工具，也有人说它是像Browserify之类的bundler，如果你仔细了解一下，你可能还是会不明白是怎么回事儿，因为官网上把webpack说成是这两者。
说实话，开始的时候对于**“webpack到底是什么“很模糊，感觉很受挫，然后我直接就把网页关了，毕竟我已经有一个构建系统了，而且我用得也非常哈皮，如果你紧赶javascript的时髦的话，像我这样，你可能在估计很快因为在各种流行的东西中频繁地跳来跳去而烧的灰飞烟灭了。
现在我有些经验了，我觉得我应该写这篇文章给那些还处在混沌中的小伙伴儿，更清楚解释一下webpack到底是什么，更重要的是它的什么地方那么棒以至于值得我们投入更多的精力。
Webpack是什么？
好的，下面我们来回答一下，介绍里面提到的那个问题，Webpack是一个构建系统还是一个模块bundler（捆绑器），恩-，两个都是 - 我不是说它两个事儿都干，我的意思是它把两者连接起来了，webpack不是先构建你的资源（assets），然后再bundle你的模块，它把你的资源本身当做模块。
更准确的说，它不是先编译你的所有的Sass文件，再优化所有的图片，再在一个地方include进来，然后bundle所有的模块，在另一个地方include到你的page上。假设你在是下面这样：
import stylesheet from &#039;styles/my-styles.scss&#039;;
import logo from &#039;img/my-logo.svg&#039;;
import someTemplate from &#039;html/some-template.html&#039;;

console.log(stylesheet); // &quot;body{font-size:12px}&quot;
console.log(logo); // &quot;data:image/svg+xml;base64,PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0iVVRGLTgiIHN0YW5kYWxvbmU9Im5[...]&quot;
console.log(someTemplate) // &quot;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Hello&lt;/h1&gt;&lt;/body&gt;&lt;/html&gt;&quot;

你的所有的资源本身被当成模块，这些模块可以被import，modify，manipulate（操作），最后被打包到你最后的bundle
为了达到这个目的，得在webpack configuration里注册loaders，loader就是当你遇到某种文件的时候，对它做相应的一种处理的一种插件，下面是一些loader的例子：
{
  // When you import a .ts file, parse it with Typescript
  test: /\.ts/,
  loader: &#039;typescript&#039;,
},
{
  // When you encounter images, compress them with image-webpack (wrapper around imagemin)
  // and then inline them as data64 URLs
  test: /\.(png|jpg|svg)/,
  loaders: [&#039;url&#039;, &#039;image-webpack&#039;],
},
{
  // When you encounter SCSS files, parse them with node-sass, then pass autoprefixer on them
  // then return the results as a string of CSS
  test: /\.scss/,
  loaders: [&#039;css&#039;, &#039;autoprefixer&#039;, &#039;sass&#039;],
}

最后在食物链的终点所有的loader返回的都是string，这样可以使webpack把资源最后包装成javascript模块。这个例子里你的Sass文件被loaders转换后，里面看起来差不多是这样。
export default &#039;body{font-size:12px}&#039;;

那你究竟为什么要用它呢？
一旦你明白webpack是做什么的，很有可能就会想到第二个问题：用它能有什么好处呢？images和CSS？还在我的JS里？玩啥呢哥们儿。好的，看下这个：很长时间我一直被告诉要把所有文件都放在一个文件里，这样来保证不浪费我们的request。
但这样导致一个最大的缺点，就是现在大多数人都把所有的资源（assets）bundle到一个单独的app.js文件里，然后把他include每一个页面，这就意味着渲染任意一个页面的时候大部分时间都浪费在加载一大堆根本用不上的资源上。如果你不这么做，那么你很有可能得手动把这些资源include到指定的页面，这就会引出一大团乱遭的依赖树去维护和跟踪如：哪些页面这个需要依赖？哪些页面style A 和Style B 起作用。
这两个方法都不对，也都不是错的。我们把webpack当做一个中间者-他不仅仅是一个构建（build）系统或者一个bundler，它是一个邪恶小精灵般的智能打包（packing）系统，正确地配置后，它甚至比你都了解你的系统栈（stack），而且它比你清楚怎么样最优优化你的系统。
我们来做一个小的app
为了让你更容易地理解webpack带来的好处，我们做一个小的app，然后用它来bundle 资源（assets），在本篇文章里我建议用Node 4 (或 5)和NPM 3因为扁平的依赖树在你用webpack的时候会避免很多让人头疼的麻烦，如果你还没有NPM3,你可以通过 npm install npm@3 -g 来安装。
$ node --version
v5.7.1
$ npm --version
3.6.0

同时我也建议你把 node_modules/.bin 加到你的PATH variable（环境变量里）以避免每次都手动打 node_modules/.bin/webpack ，后面的所有例子都不会显示我要执行的命令行的 node_modules/.bin 部分。
基本引导
我们开始，先创建个project，安装上webpack，我们也加上jquery好在后面证明一些东西。
$ npm init -y
$ npm install jquery --save
$ npm install webpack --save-dev

现在来我们创建一个app入口，用纯ES5 （in plain ES5）
src/index.js
var $ = require(&#039;jquery&#039;);

$(&#039;body&#039;).html(&#039;Hello&#039;);

在一个webpack.config.js文件里建webpack configuration，webpack configuration是javascript，需要export 一个object
webpack.config.js
module.exports = {
    entry:  &#039;./src&#039;,
    output: {
	    path: &#039;builds&#039;,
	    filename: &#039;bundle.js&#039;,
    },
};

这里，entry告诉webpack那个文件是你的app的入口点。这些是你的主文件，他们在依赖树的顶端，然后我们告诉它编译我们的bundle 到bundle.js文件放在builds目录下，再创建相应的index HTML
&lt;!DOCTYPE html&gt;
&lt;html&gt;
    &lt;body&gt;
	    &lt;h1&gt;My title&lt;/h1&gt;
	    &lt;a&gt;Click me&lt;/a&gt;

	    &lt;script src=&quot;builds/bundle.js&quot;&gt;&lt;/script&gt;
    &lt;/body&gt;
&lt;/html&gt;

跑一下webpack，如果一切正常，会看见一个信息告诉我们正确地编译了bundle.js
$ webpack
Hash: d41fc61f5b9d72c13744
Version: webpack 1.12.14
Time: 301ms
AssetSize  Chunks Chunk Names
bundle.js  268 kB   0  [emitted]  main
   [0] ./src/index.js 53 bytes {0} [built]
+ 1 hidden modules

这里webpack告诉你你的bundle.js包含了我们的入口点（index.js）和一个隐藏的模块，这个就是jquery，默认情况下webpack把不是你的模块会隐藏掉，如果想看见webpack编译的所有的模块 ，我们可以加--display-modules 参数
$ webpack --display-modules
bundle.js  268 kB   0  [emitted]  main
   [0] ./src/index.js 53 bytes {0} [built]
   [1] ./~/jquery/dist/jquery.js 259 kB {0} [built]

你也可以运行 webpack --watch 来自动监视文件的变化，如果有变化，自动重新编译。
搭建我们的第一个loader
现在还记得我们怎么讨论webpack可以导入CSS和HTML还有各种文件的吗？什么时候能排上用场呢？好的，如果你跟随着过去几年朝着web组件方向的大跃进（Angular 2, Vue, React, Polymer, X-Tag, etc.）估计你听过这样一个观点：你的app是如果用一套可重用，自包含的UI组件搭建的话相比较于一个单独的内聚的UI将会变得更容易维护，这个可重用的组件就是web 组件（在这里我说的比较简单），现在为了让组件变成真正的自包含，需要把组件需要的所有的东西封装到他们自己的内部，我们来考虑一个button，它里面肯定有一些HTML，而且还有一些JS来保证它的交互性，还得来一些style，这些东西如果需要的时候一起加载进来会非常棒，只有在我们导入button组件的时候，我们才会得到所有的这些资源文件（asset）。
来我们写一个button，首先我先假设你们已经熟悉了ES2015 ，我们先加入babel这个loader。想要在webpack里安装一个loader，有两步需要做：1. npm install {whatever}-loader,2. 把它加到你的Webpack configuration里的module.loaders部分
我们开始，现在我们要加babel，所以：
$ npm install babel-loader --save-dev

我们也得安装	Babel ，因为现在我们这个case，loader不会安装它，我们需要装babel-core package 和 es2015 preset:
$ npm install babel-core babel-preset-es2015 --save-dev.

我们现在创建.babelrc文件，告诉bable用那个preset，这是一个json文件让你配置Babel在你的code上执行哪种变体，我们现在这个我们我告诉它用es2015 preset
.babelrc
{ &quot;presets&quot;: [&quot;es2015&quot;] }
现在babel配完了，我们可以更新我们的配置：我们想要什么？我们想babel在我们所有的.js结尾的文件上运行，但是由于webpack遍历所有的依赖，我们想避免babel运行在第三方代码上，如jquery，所以我们可以再稍微过滤一下，loaders既可以有include也可以由exclude，可以是string，regex（正则表达式），一个callback（回调），随便用哪个。因为我们想让babel值运行在我们的文件上，所以我们只include我们自己的source目录：
module.exports = {
    entry:  &#039;./src&#039;,
	    output: {
		    path: &#039;builds&#039;,
		   	 filename: &#039;bundle.js&#039;,
		    },
		    module: {
		    loaders: [
		    {
			    test:   /\.js/,
			    loader: &#039;babel&#039;,
			    include: __dirname + &#039;/src&#039;,
		    }
	    ],
    }
};

我们可以用ES6重写一下我们的index.js这个小文件，由于我们引入了babel，从这里开始后面的所有例子都用ES6.
import $ from &#039;jquery&#039;;

$(&#039;body&#039;).html(&#039;Hello&#039;);

写个小组件
我们来写一个小的Button 组件，它有一些SCSS style，一个HTML template，和一些behavior，那么我们安装一些我们需要的东西。首先我们用一个非常轻量的模板包Mustache ，我们也需要给Sass和HTML用的loaders，因为结果会通过管道（pipe）从一个loader传到另一个，我们需要一个Sass loader，现在一旦我们有了css，会有多种方式处理它，当前阶段，我们用一个叫style-loader的loader，它会接收一段CSS，然后动态地把它插入到页面。
$ npm install mustache --save
$ npm install css-loader style-loader html-loader sass-loader node-sass --save-dev

为了让webpack用管道（pipe）把东西从一个loader传到另一个loader，我们简传入几个loader方向由右到左，用一个！分开，或者你可以用一个数组通过loaders属性，不是loader
{
    test:/\.js/,
    loader:  &#039;babel&#039;,
    include: __dirname + &#039;/src&#039;,
},
{
test:   /\.scss/,
    loader: &#039;style!css!sass&#039;,
    // Or
    loaders: [&#039;style&#039;, &#039;css&#039;, &#039;sass&#039;],
},
{
    test:   /\.html/,
    loader: &#039;html&#039;,
}

现在我们把loaders准备好了，我们来写一个button：
src/Components/Button.scss
.button {
  background: tomato;
  color: white;
}

src/Components/Button.html
&lt;a class=&quot;button&quot; href=&quot;{{link}}&quot;&gt;{{text}}&lt;/a&gt;

src/Components/Button.js
import $ from &#039;jquery&#039;;
import template from &#039;./Button.html&#039;;
import Mustache from &#039;mustache&#039;;
import &#039;./Button.scss&#039;;

import $ from &#039;jquery&#039;;
import template from &#039;./Button.html&#039;;
import Mustache from &#039;mustache&#039;;
import &#039;./Button.scss&#039;;

export default class Button {
		constructor(link) {
		this.link = link;
	}

	onClick(event) {
		event.preventDefault();
		alert(this.link);
	}

	render(node) {
		const text = $(node).text();

		// Render our button
		$(node).html(Mustache.render(template, {text}));

		// Attach our listeners
		$(&#039;.button&#039;).click(this.onClick.bind(this));
	}
}

你的Button现在是百分之百自包含的，无论什么时候导入，无论运行在什么context，它有所有需要的东西，然后正确地render（渲染），现在我们只需要把我们的Button render到我们的网页上（page）：
src/index.js
js import Button from ‘./Components/Button’;

const button = new Button(‘google.com’); button.render(‘a’); 

我们来运行一下webpack，然后刷新一下页面，你应该就能看见你的挺丑的button出来了。

现在你已经学了怎么配置loader和怎么给你的app的每一个部分定义dependency（依赖），现在可能看起来不太重要这些，但现在我们来把我们的例子再做一下改进：
code分片（splitting)
这个例子还不错什么都有，但可能我们不总需要我们的Button，可能有些界面不会有 a（link）来让我们渲染Button用，在这种情况下，我们不需要导入所有的Button的style（式样），template（模板），Mustache 和一切相关的东西，对吧？“Monolithic bundle”（单片绑定） VS “Unmaintainable manual imports”（不好维护的手动导入）. 这种idea是，你在你的代码里定义split point（分割点）：你的code中可以轻松拆分开到单独文件中的部分，然后按需加载，语法非常简单：
import $ from &#039;jquery&#039;;

// This is a split point
require.ensure([], () =&gt; {
  // All the code in here, and everything that is imported
  // will be in a separate file
  const library = require(&#039;some-big-library&#039;);
  $(&#039;foo&#039;).click(() =&gt; library.doSomething());
});

在require.ensure callback 里的任何东西都会被拆分成chunk（代码块）-一个webpack需要的时候会通过ajax单独加载的bundle，这意味着我们基本上有这些：
bundle.js
|- jquery.js
|- index.js // our main file
chunk1.js
|- some-big-libray.js
|- index-chunk.js // the code in the callback


你无需导入chunk1.js。webpack只有在需要它的时候才会加载它，这意味着你可以把你的code按照各种逻辑分成多块，我们将在下面的例子中这么做，我们只想在page里有link的的时候才需要Button
src/index.js
if (document.querySelectorAll(&#039;a&#039;).length) {
    require.ensure([], () =&gt; {
	    const Button = require(&#039;./Components/Button&#039;).default;
	  	  const button = new Button(&#039;google.com&#039;);

	    button.render(&#039;a&#039;);
    });
}

注意，用require的时候，如果你想default export 你需要通过.default手动获取它，
因为require 不会同时处理default 和 normal（正常） exports，所以你必须指定返回哪个，不过import有一个系统处理这个，所以它已经知道了(例如： import foo from &#039;bar&#039;)vs import {baz} from &#039;bar&#039;).
