usage
State Machine in Event Loop
//               ________
//            --|Snapshot|                 timeout
//            |  --------                  ______
// recover    |       ^                   |      |
// snapshot / |       |snapshot           |      |
// higher     |       |                   v      |     recv majority votes
// term       |    --------    timeout    -----------                        -----------
//            |-&gt; |Follower| ----------&gt; | Candidate |--------------------&gt; |  Leader   |
//                 --------               -----------                        -----------
//                    ^          higher term/ |                         higher term |
//                    |            new leader |                                     |
//                    |_______________________|____________________________________ |


func (s *server) loop() {
	defer s.debugln(&quot;server.loop.end&quot;)

	state := s.State()

	for state != Stopped {
		s.debugln(&quot;server.loop.run &quot;, state)
		switch state {
		case Follower:
			s.followerLoop()
		case Candidate:
			s.candidateLoop()
		case Leader:
			s.leaderLoop()
		case Snapshotting:
			s.snapshotLoop()
		}
		state = s.State()
	}
}

Log Replication
append entries processing in event loop
// Processes the &quot;append entries&quot; request.
func (s *server) processAppendEntriesRequest(req *AppendEntriesRequest) (*AppendEntriesResponse, bool) {
	s.traceln(&quot;server.ae.process&quot;)

	if req.Term &lt; s.currentTerm {
		s.debugln(&quot;server.ae.error: stale term&quot;)
		return newAppendEntriesResponse(s.currentTerm, false, s.log.currentIndex(), s.log.CommitIndex()), false
	}

	if req.Term == s.currentTerm {
		_assert(s.State() != Leader, &quot;leader.elected.at.same.term.%d\n&quot;, s.currentTerm)

		// step-down to follower when it is a candidate
		if s.state == Candidate {
			// change state to follower
			s.setState(Follower)
		}

		// discover new leader when candidate
		// save leader name when follower
		s.leader = req.LeaderName
	} else {
		// Update term and leader.
		s.updateCurrentTerm(req.Term, req.LeaderName)
	}

	// Reject if log doesn&#039;t contain a matching previous entry.
	if err := s.log.truncate(req.PrevLogIndex, req.PrevLogTerm); err != nil {
		s.debugln(&quot;server.ae.truncate.error: &quot;, err)
		return newAppendEntriesResponse(s.currentTerm, false, s.log.currentIndex(), s.log.CommitIndex()), true
	}

	// Append entries to the log.
	if err := s.log.appendEntries(req.Entries); err != nil {
		s.debugln(&quot;server.ae.append.error: &quot;, err)
		return newAppendEntriesResponse(s.currentTerm, false, s.log.currentIndex(), s.log.CommitIndex()), true
	}

	// Commit up to the commit index.
	if err := s.log.setCommitIndex(req.CommitIndex); err != nil {
		s.debugln(&quot;server.ae.commit.error: &quot;, err)
		return newAppendEntriesResponse(s.currentTerm, false, s.log.currentIndex(), s.log.CommitIndex()), true
	}

	// once the server appended and committed all the log entries from the leader

	return newAppendEntriesResponse(s.currentTerm, true, s.log.currentIndex(), s.log.CommitIndex()), true
}

// Processes the &quot;append entries&quot; response from the peer. This is only
// processed when the server is a leader. Responses received during other
// states are dropped.
func (s *server) processAppendEntriesResponse(resp *AppendEntriesResponse) {
	// If we find a higher term then change to a follower and exit.
	if resp.Term() &gt; s.Term() {
		s.updateCurrentTerm(resp.Term(), &quot;&quot;)
		return
	}

	// panic response if it&#039;s not successful.
	if !resp.Success() {
		return
	}

	// if one peer successfully append a log from the leader term,
	// we add it to the synced list
	if resp.append == true {
		s.syncedPeer[resp.peer] = true
	}

	// Increment the commit count to make sure we have a quorum before committing.
	if len(s.syncedPeer) &lt; s.QuorumSize() {
		return
	}

	// Determine the committed index that a majority has.
	var indices []uint64
	indices = append(indices, s.log.currentIndex())
	for _, peer := range s.peers {
		indices = append(indices, peer.getPrevLogIndex())
	}
	sort.Sort(sort.Reverse(uint64Slice(indices)))

	// We can commit up to the index which the majority of the members have appended.
	commitIndex := indices[s.QuorumSize()-1]
	committedIndex := s.log.commitIndex

	if commitIndex &gt; committedIndex {
		// leader needs to do a fsync before committing log entries
		s.log.sync()
		s.log.setCommitIndex(commitIndex)
		s.debugln(&quot;commit index &quot;, commitIndex)
	}
}

append entries processing in heatbeat
//--------------------------------------
// Heartbeat
//--------------------------------------
// The event loop that is run when the server is in a Leader state.
func (s *server) leaderLoop() {
...
    // Update the peers prevLogIndex to leader&#039;s lastLogIndex and start heartbeat.
    for _, peer := range s.peers {
        peer.setPrevLogIndex(logIndex)
        peer.startHeartbeat()
    }
...
}



// Listens to the heartbeat timeout and flushes an AppendEntries RPC.
func (p *Peer) heartbeat(c chan bool) {
    ...

	ticker := time.Tick(p.heartbeatInterval)

	debugln(&quot;peer.heartbeat: &quot;, p.Name, p.heartbeatInterval)

	for {
		select {
		...
		case &lt;-ticker:
			start := time.Now()
			p.flush()
			duration := time.Now().Sub(start)
			p.server.DispatchEvent(newEvent(HeartbeatEventType, duration, nil))
		}
	}
}

func (p *Peer) flush() {
	debugln(&quot;peer.heartbeat.flush: &quot;, p.Name)
	prevLogIndex := p.getPrevLogIndex()
	log.Print(&quot;heartbeat flush,prev log index is:&quot;,prevLogIndex)
	term := p.server.currentTerm
    // Retrieves a list of entries after a given index as well as the term of the
    // index provided. A nil list of entries is returned if the index no longer
    // exists because a snapshot was made.
	entries, prevLogTerm := p.server.log.getEntriesAfter(prevLogIndex, p.server.maxLogEntriesPerRequest)

	if entries != nil {
		p.sendAppendEntriesRequest(newAppendEntriesRequest(term, prevLogIndex, prevLogTerm, p.server.log.CommitIndex(), p.server.name, entries))
	} else {
		p.sendSnapshotRequest(newSnapshotRequest(p.server.name, p.server.snapshot))
	}
}

//--------------------------------------
// Append Entries
//--------------------------------------

// Sends an AppendEntries request to the peer through the transport.
func (p *Peer) sendAppendEntriesRequest(req *AppendEntriesRequest) {
	tracef(&quot;peer.append.send: %s-&gt;%s [prevLog:%v length: %v]\n&quot;,
		p.server.Name(), p.Name, req.PrevLogIndex, len(req.Entries))

	resp := p.server.Transporter().SendAppendEntriesRequest(p.server, p, req)
	if resp == nil {
		p.server.DispatchEvent(newEvent(HeartbeatIntervalEventType, p, nil))
		debugln(&quot;peer.append.timeout: &quot;, p.server.Name(), &quot;-&gt;&quot;, p.Name)
		return
	}
	traceln(&quot;peer.append.resp: &quot;, p.server.Name(), &quot;&lt;-&quot;, p.Name)

	p.setLastActivity(time.Now())
	// If successful then update the previous log index.
	p.Lock()
	if resp.Success() {
		if len(req.Entries) &gt; 0 {
			p.prevLogIndex = req.Entries[len(req.Entries)-1].GetIndex()
		}
		traceln(&quot;peer.append.resp.success: &quot;, p.Name, &quot;; idx =&quot;, p.prevLogIndex)
	} else {
		if resp.Term() &gt; p.server.Term() {
			// this happens when there is a new leader comes up that this *leader* has not
			// known yet.
			// this server can know until the new leader send a ae with higher term
			// or this server finish processing this response.
			debugln(&quot;peer.append.resp.not.update: new.leader.found&quot;)
		} else if resp.Term() == req.Term &amp;&amp; resp.CommitIndex() &gt;= p.prevLogIndex {
			// we may miss a response from peer
			// so maybe the peer has committed the logs we just sent
			// but we did not receive the successful reply and did not increase
			// the prevLogIndex

			// peer failed to truncate the log and sent a fail reply at this time
			// we just need to update peer&#039;s prevLog index to commitIndex

			p.prevLogIndex = resp.CommitIndex()
			debugln(&quot;peer.append.resp.update: &quot;, p.Name, &quot;; idx =&quot;, p.prevLogIndex)

		} else if p.prevLogIndex &gt; 0 {
            // If it was unsuccessful then decrement the previous log index and
            // we&#039;ll try again next time.
			// Decrement the previous log index down until we find a match. Don&#039;t
			// let it go below where the peer&#039;s commit index is though. That&#039;s a
			// problem.
			p.prevLogIndex--
			// if it is not enough, we directly decrease to the index of the peer log
			if p.prevLogIndex &gt; resp.Index() {
				p.prevLogIndex = resp.Index()
			}

			debugln(&quot;peer.append.resp.decrement: &quot;, p.Name, &quot;; idx =&quot;, p.prevLogIndex)
		}
	}
	p.Unlock()

	// Attach the peer to resp, thus server can know where it comes from
	resp.peer = p.Name
	// Send response to server for processing.
	p.server.sendAsync(resp)
}

post/2016-12-18-bolt.content:
boltdb in-depth analysis

BoltDB中的Bucket类似于传统关系型数据库的”表”。BoltDB通过Bucket将一个庞大的数据库划分成诸多的命名空间。用户在每个命名空间内存储KV数据，通过此种办法可以提高数据的搜索效率。
例如，一个BoltDB中可：
创建User Bucket，用于记录用户信息(存储的K是用户名，而Value是用户详情)
创建Order Bucket，用户记录用户订单信息(存储的K是用户名，而Value则是订单详情)
……
与传统关系型数据库中的表所不同的是，Bucket是一种嵌套型的结构。传统关系型数据库如Mysql中表下无法再创建子表，而BoltDB中的Bucket可以创建子Bucket.
Inline Bucket
Bucket本质上属于一个逻辑概念。Bucket里面存储的都是Key/Value记录。BoltDB中创建的每个Bucket也会作为一个KV记录被持久化存储在数据文件中。为了提高查询效率，BoltDB对Bucket的存储结构作了一定优化，对于容量不大的Bucket进行inline存储：即将Bucket内的KV记录与Bucket的KV记录连续存放。这样做的好处显而易见：搜寻到了Bucket，即可遍历出该Bucket下的所有KV记录。但是也不能将Bucket都以Inline方式存储，当一个Bucket下的KV记录数超过一定限制时，便不再适合这种方式存储。
Inline Bucket在磁盘上的存储结构如下图所示：


key: 存储Bucket name
value: 存放bucket value，对于inline bucket，其value包含 bucket header{root, sequence}，以及bucket body，bucket body是一个模拟的page，包含page header，以及page body，page body中记录该Bucket内创建的所有sub Bucket以及普通的KV记录，每个KV记录对应一个item。

Bucket存储
Bucket是BoltDB内划分命名空间的基础。所有的KV记录都必须被存储在某个Bucket之下。而Bucket在BoltDB内其实也只是一个普通的KV记录而已。
Bucket的内存数据结构
// Bucket represents a collection of key/value pairs inside the database.
type Bucket struct {
	*bucket
	tx       *Tx                // the associated transaction
	buckets  map[string]*Bucket // subbucket cache
	page     *page              // inline page reference
	rootNode *node              // materialized node for the root page.
	nodes    map[pgid]*node     // node cache

	// Sets the threshold for filling nodes when they split. By default,
	// the bucket will fill to 50% but it can be useful to increase this
	// amount if you know that your write workloads are mostly append-only.
	//
	// This is non-persisted across transactions so it must be set in every Tx.
	FillPercent float64
}


bucket:Bucket的磁盘描述结构
buckets: Bucket的孩子Bucket，每个Bucket下可创建子Bucket
page: Bucket的Inline page引用
rootNode: Bucket的root page的内存节点
nodes: node的cache

这其中有几个成员值得详细一说：

page: 对于存储KV数量不多的Bucket，其KV记录会与Bucket记录连续存放，这种Bucket被称为Inline Bucket。而每个Bucket需要记录其内存储KV的引用，对于Inline Bucket，其page指向的是Bucket后的连续地址空间.

type page struct {
	id       pgid
	flags    uint16
	count    uint16
	overflow uint32
	ptr      uintptr
}


bucket:Bucket在磁盘上的存储KV记录的Value部分的头部。对于Inline Bucket，其内创建的KV记录存储在bucket之后的page，而这个page(fake page)在物理位置上与bucket是连续存放的。

// bucket represents the on-file representation of a bucket.
// This is stored as the &quot;value&quot; of a bucket key. If the bucket is small enough,
// then its root page can be stored inline in the &quot;value&quot;, after the bucket
// header. In the case of inline buckets, the &quot;root&quot; will be 0.
type bucket struct {
	root     pgid   // page id of the bucket&#039;s root-level page
	sequence uint64 // monotonically incrementing, used by NextSequence()
}

// node represents an in-memory, deserialized page.
type node struct {
	bucket     *Bucket
	isLeaf     bool
	unbalanced bool
	spilled    bool
	key        []byte
	pgid       pgid
	parent     *node
	children   nodes
	inodes     inodes
}

type inodes []inode

// inode represents an internal node inside of a node.
// It can be used to point to elements in a page or point
// to an element which hasn&#039;t been added to a page yet.
type inode struct {
	flags uint32
	pgid  pgid
	key   []byte
	value []byte
}

Root Bucket Init
BoltDB中的Bucket是一个嵌套结构，因此，系统中必然存在一个root bucket。用户创建的所有Bucket都是该Bucket的子孙。Root Bucket在DB被初次创建的时候而创建的。DB被创建时会写入一系列系统元数据，其中就包括root bucket信息，这些元数据被存储在BoltDB专门的meta page中，如下：
// init creates a new database file and initializes its meta pages.
func (db *DB) init() error {
	// Set the page size to the OS page size.
	db.pageSize = os.Getpagesize()

	// Create two meta pages on a buffer.
	buf := make([]byte, db.pageSize*4)
	for i := 0; i &lt; 2; i++ {
		p := db.pageInBuffer(buf[:], pgid(i))
		p.id = pgid(i)
		p.flags = metaPageFlag

		// Initialize the meta page.
		m := p.meta()
		m.magic = magic
		m.version = version
		m.pageSize = uint32(db.pageSize)
		m.freelist = 2
		m.root = bucket{root: 3}
		m.pgid = 4
		m.txid = txid(i)
		m.checksum = m.sum64()
	}

	// Write an empty freelist at page 3.
	p := db.pageInBuffer(buf[:], pgid(2))
	p.id = pgid(2)
	p.flags = freelistPageFlag
	p.count = 0

	// Write an empty leaf page at page 4.
	p = db.pageInBuffer(buf[:], pgid(3))
	p.id = pgid(3)
	p.flags = leafPageFlag
	p.count = 0

	// Write the buffer to our data file.
	if _, err := db.ops.writeAt(buf, 0); err != nil {
		return err
	}
	if err := fdatasync(db); err != nil {
		return err
	}

	return nil
}


从上面的BoltDB初始化过程可以发现，系统root Bucket的page id是3，意味着在root bucket下创建子Bucket的话，子Bucket的记录一定会写入page 3。
创建Bucket流程
我们这里以两种情形来说明如何创建Bucket：在root Bucket下创建Bucket和在非root Bucket下创建Bucket。
root Bucket下创建Bucket
无论是哪种方式Bucket，创建Bucket的第一步都是定位到父Bucket所在地(Bucket存储所在的page)。而我们前面说过，root Bucket的起始page id为3。 因此，在root Bucket创建sub Bucket的第一步便是在page 3上搜索Bucket应当的插入位置。
// CreateBucket creates a new bucket at the given key and returns the new bucket.
// Returns an error if the key already exists, if the bucket name is blank, or if the bucket name is too long.
// The bucket instance is only valid for the lifetime of the transaction.
func (b *Bucket) CreateBucket(key []byte) (*Bucket, error) {
	if b.tx.db == nil {
		return nil, ErrTxClosed
	} else if !b.tx.writable {
		return nil, ErrTxNotWritable
	} else if len(key) == 0 {
		return nil, ErrBucketNameRequired
	}

	// Move cursor to correct position.
	c := b.Cursor()
	k, _, flags := c.seek(key)

	// Return an error if there is an existing key.
	if bytes.Equal(key, k) {
		if (flags &amp; bucketLeafFlag) != 0 {
			return nil, ErrBucketExists
		}
		return nil, ErrIncompatibleValue
	}

	// Create empty, inline bucket.
	var bucket = Bucket{
		bucket:      &amp;bucket{},
		rootNode:    &amp;node{isLeaf: true},
		FillPercent: DefaultFillPercent,
	}
	var value = bucket.write()

	// Insert into node.
	key = cloneBytes(key)
	c.node().put(key, key, value, 0, bucketLeafFlag)

	// Since subbuckets are not allowed on inline buckets, we need to
	// dereference the inline page, if it exists. This will cause the bucket
	// to be treated as a regular, non-inline bucket for the rest of the tx.
	b.page = nil

	return b.Bucket(key), nil
}

上述过程看起来非常简单：
为父Bucket(也就是root Bucket)创建Cursor，并定位子Bucket的位置； 创建一个Bucket，当然，起始的时候肯定是一个Inline Bucket； 将2创建的Bucket写入到1中Cursor定位的地方 然后此事就算了结了
Cursor其实只是保存了查找过程中的搜索路径而已。类似一个stack，栈底是搜索路径的起点，栈顶是搜索路径的终点。Cursor.seek(key)完成后，Cursor中就已经记录了到key的搜索路径。
第一次创建Bucket之前，root Bucket所在的page 3此时空无一物。

显然我们第一个创建的Bucket会落在item1的位置。于是，page 3的内容变成了如下所示：

那么，root Bucket下的第一个Bucket算是正式创建成功，接下来要做的就是向该Bucket内插入KV记录了。
已有Bucket下创建Bucket
前面描述过了在root Bucket下创建Bucket的过程，这里我们再来研究下如何在已经创建过的Bucket下创建子Bucket的过程。在现有Bucket下创建子Bucket与root下创建Bucket的过程其实是一样的，因为代码用的都是同一套。它们的区别在于搜寻的路径不一样，在root Bucket下创建Bucket是从root page(page 3)开始，而在现有Bucket下创建子Bucket则搜寻路径是从该Bucket的rootNode开始的。
在已有Bucket下面创建新Bucket的话，第一步是打开该已有的Bucket，填充该父Bucket的一些信息，然后在该父Bucket下创建子Bucket，我们先来看看怎么打开一个Bucket。
// Bucket retrieves a nested bucket by name.
// Returns nil if the bucket does not exist.
// The bucket instance is only valid for the lifetime of the transaction.
func (b *Bucket) Bucket(name []byte) *Bucket {
	if b.buckets != nil {
		if child := b.buckets[string(name)]; child != nil {
			return child
		}
	}

	// Move cursor to key.
	c := b.Cursor()
	k, v, flags := c.seek(name)

	// Return nil if the key doesn&#039;t exist or it is not a bucket.
	if !bytes.Equal(name, k) || (flags&amp;bucketLeafFlag) == 0 {
		return nil
	}

	// Otherwise create a bucket and cache it.
	var child = b.openBucket(v)
	if b.buckets != nil {
		b.buckets[string(name)] = child
	}

	return child
}

这里首先是在root Bucket下查找该Bucket的KV记录，注意这里的Bucket还是一个Inline Bucket，因此其value包含了一大坨内容，这个在前面已经详细描述过，我们再来复习下，对于一个Inline Bucket，其KV内容如下：

好，那接下来就是openBucket啦：
// Helper method that re-interprets a sub-bucket value
// from a parent into a Bucket
func (b *Bucket) openBucket(value []byte) *Bucket {
	var child = newBucket(b.tx)

	// If unaligned load/stores are broken on this arch and value is
	// unaligned simply clone to an aligned byte array.
	unaligned := brokenUnaligned &amp;&amp; uintptr(unsafe.Pointer(&amp;value[0]))&amp;3 != 0

	if unaligned {
		value = cloneBytes(value)
	}

	// If this is a writable transaction then we need to copy the bucket entry.
	// Read-only transactions can point directly at the mmap entry.
	if b.tx.writable &amp;&amp; !unaligned {
		child.bucket = &amp;bucket{}
		*child.bucket = *(*bucket)(unsafe.Pointer(&amp;value[0]))
	} else {
		child.bucket = (*bucket)(unsafe.Pointer(&amp;value[0]))
	}

	// Save a reference to the inline page if the bucket is inline.
	if child.root == 0 {
		child.page = (*page)(unsafe.Pointer(&amp;value[bucketHeaderSize]))
	}

	return &amp;child
}

对于Inline Bucket，child.root肯定是0，因此，child.page就是Bucket value的bucket之后的内容，这其实是一个模拟的page。这样，Bucket被打开了，其root以及page也被正确初始化了。接下来就可以在Bucket下创建孩子Bucket了。
现在父Bucket也打开了，我们继续刚刚的话题，在父Bucket下创建子Bucket，与在root Bucket下创建子Bucket流程类似，只是这一次，我们搜索路径的起点是父Bucket.root，由于父Bucket是一个Inline Bucket，父Bucket.root是0，在搜索的时候便是从rootNode开始，如下：
// seek moves the cursor to a given key and returns it.
// If the key does not exist then the next key is used.
func (c *Cursor) seek(seek []byte) (key []byte, value []byte, flags uint32) {
	_assert(c.bucket.tx.db != nil, &quot;tx closed&quot;)

	// Start from root page/node and traverse to correct page.
	c.stack = c.stack[:0]
	c.search(seek, c.bucket.root)
	ref := &amp;c.stack[len(c.stack)-1]

	// If the cursor is pointing to the end of page/node then return nil.
	if ref.index &gt;= ref.count() {
		return nil, nil, 0
	}

	// If this is a bucket then return a nil value.
	return c.keyValue()
}

// search recursively performs a binary search against a given page/node until it finds a given key.
func (c *Cursor) search(key []byte, pgid pgid) {
	p, n := c.bucket.pageNode(pgid)
	if p != nil &amp;&amp; (p.flags&amp;(branchPageFlag|leafPageFlag)) == 0 {
		panic(fmt.Sprintf(&quot;invalid page type: %d: %x&quot;, p.id, p.flags))
	}
	e := elemRef{page: p, node: n}
	c.stack = append(c.stack, e)

	// If we&#039;re on a leaf page/node then find the specific node.
	if e.isLeaf() {
		c.nsearch(key)
		return
	}

	if n != nil {
		c.searchNode(key, n)
		return
	}
	c.searchPage(key, p)
}

从上面看到，对于Inline Bucket，其搜索路径的起点是Bucket.page，这是在Bucket在Open的时候被加载并初始化的，我们已经在前面仔细描述过。好，到这里我们开始从Bucket.page开始搜索，假如已经找到了子Bucket应该存储的位置，其实就是父Bucket的page内的第一项，将子Bucket的内容(KV)写入以后，磁盘上的存储结构就变成了下面这样：

Bucket内插入KV
Bucket内插入KV与我们上面说的Bucket下创建子Bucket逻辑几无二致，只是插入的记录的数据格式不同罢了，插入子Bucket的时候我们还需要给这个子Bucket分配一个BucketHeader等等，比较复杂。写入普通KV记录看起来就简单了许多，其流程是先搜寻到记录应该插入的位置，然后将KV记录插入在该位置，这与创建Bucket流程没什么不同：
// Put sets the value for a key in the bucket.
// If the key exist then its previous value will be overwritten.
// Supplied value must remain valid for the life of the transaction.
// Returns an error if the bucket was created from a read-only transaction, if the key is blank, if the key is too large, or if the value is too large.
func (b *Bucket) Put(key []byte, value []byte) error {
	if b.tx.db == nil {
		return ErrTxClosed
	} else if !b.Writable() {
		return ErrTxNotWritable
	} else if len(key) == 0 {
		return ErrKeyRequired
	} else if len(key) &gt; MaxKeySize {
		return ErrKeyTooLarge
	} else if int64(len(value)) &gt; MaxValueSize {
		return ErrValueTooLarge
	}

	// Move cursor to correct position.
	c := b.Cursor()
	k, _, flags := c.seek(key)

	// Return an error if there is an existing key with a bucket value.
	if bytes.Equal(key, k) &amp;&amp; (flags&amp;bucketLeafFlag) != 0 {
		return ErrIncompatibleValue
	}

	// Insert into node.
	key = cloneBytes(key)
	c.node().put(key, key, value, 0, 0)

	return nil
}

在bucket内插入普通KV记录后，其内部存储结构如下所示：（注意：我们说的还是Inline Bucket哦）

post/2016-12-22-codis.content:
codis in-depth analysis

Architecture
Codis由以下组件组成：


Codis Server：基于 redis分支开发。增加了额外的数据结构，以支持 slot 有关的操作以及数据迁移指令。具体的修改可以参考文档 redis 的修改。


Codis Proxy：客户端连接的 Redis 代理服务, 实现了 Redis 协议。 除部分命令不支持以外(不支持的命令列表)，表现的和原生的 Redis 没有区别（就像 Twemproxy）。

对于同一个业务集群而言，可以同时部署多个 codis-proxy 实例
不同 codis-proxy 之间由 codis-dashboard 保证状态同步



Codis Dashboard：集群管理工具，支持 codis-proxy、codis-server 的添加、删除，以及据迁移等操作。在集群状态发生改变时，codis-dashboard 维护集群下所有 codis-proxy 的状态的一致性。

对于同一个业务集群而言，同一个时刻 codis-dashboard 只能有 0个或者1个；
所有对集群的修改都必须通过 codis-dashboard 完成。



Codis Admin：集群管理的命令行工具。

可用于控制 codis-proxy、codis-dashboard 状态以及访问外部存储。



Codis FE：集群管理界面。

多个集群实例共享可以共享同一个前端展示页面；
通过配置文件管理后端 codis-dashboard 列表，配置文件可自动更新。



Codis HA：为集群提供高可用。

依赖 codis-dashboard 实例，自动抓取集群各个组件的状态；
会根据当前集群状态自动生成主从切换策略，并在需要时通过 codis-dashboard 完成主从切换。



Storage：为集群状态提供外部存储。

提供 Namespace 概念，不同集群的会按照不同 product name 进行组织；
目前仅提供了 Zookeeper 和 Etcd 两种实现，但是提供了抽象的 interface 可自行扩展




Codis-Server
Codis采用预先分片（Pre-Sharding）机制，事先规定好了，分成1024个slots，这些路由信息保存在ZooKeeper/Etcd中,同时维护Codis Server Group信息，并提供分布式锁等服务．
redis源码server.c部分修改主要是针对Slot的维护命令，参见slot.c
