// PIPELINE #3: buffer
// controls the packet sending for the client
// packet sending goroutine
func (buf *Buffer) start() {
	defer utils.PrintPanicStack()
	for {
		select {
		case data := &lt;-buf.pending:
			buf.raw_send(data)
		case &lt;-buf.ctrl: // receive session end signal
			close(buf.pending)
			// close the connection
			buf.conn.Close()
			return
		}
	}
}

