stack traceback:
        ./examples/simpledb.lua:11: in local &#039;f&#039;
        ./examples/simpledb.lua:20: in upvalue &#039;dispatch&#039;
        ./lualib/skynet/remotedebug.lua:150: in upvalue &#039;f&#039;
        ./lualib/skynet.lua:111: in function &lt;./lualib/skynet.lua:105&gt;
